// ================= animaciones del mapa =================
function exNpcPos(n){if(n.mv){const p=Math.min(1,n.mv.t/n.mv.d);return{x:n.mv.x0+(n.px-n.mv.x0)*p,y:n.mv.y0+(n.py-n.mv.y0)*p,fr:p<.55?((n.step||0)%2?1:3):0}}return{x:n.px,y:n.py,fr:0}}
function exNpcStep(n,dt){n.mv.t+=dt;if(n.mv.t>=n.mv.d){n.mv=null;const c=exAt(n.px,n.py);if(c==="T"||c==="d"||c==="g")EX.rustleN={x:n.px,y:n.py,t:performance.now()}}}
// los entrenadores miran a su alrededor, respiran y dan algún paso por su zona
function exNpcAI(dt,ts){if(EX.trans||EX.walkTo||EX.alert)return;
  for(const n of EX.npcs){if(n.still)continue;if(n.ph==null)n.ph=Math.random()*3;if(n.mv)continue;
    if(!n.nt){n.nt=ts+1500+Math.random()*2500;continue}if(ts<n.nt)continue;n.nt=ts+1800+Math.random()*3200;
    const r=Math.random();
    if(r<.55){const ds=["u","d","l","r"].filter(d=>d!==n.f);n.f=ds[Math.floor(Math.random()*ds.length)]}
    else if(r<.85){const d=["u","d","l","r"][Math.floor(Math.random()*4)],[dx,dy]=EXDIR[d],x=n.px+dx,y=n.py+dy;n.f=d;
      if(Math.abs(x-n.x)<=1&&Math.abs(y-n.y)<=1&&!exBlocked(x,y)&&!(x===EX.x&&y===EX.y)&&!(EX.mv&&EX.mv&&x===EX.x&&y===EX.y)&&!/[~w]/.test(exAt(x,y))){n.mv={x0:n.px,y0:n.py,t:0,d:320};n.px=x;n.py=y;n.step=(n.step||0)+1}}
    if(!n.beat&&!EX.mv&&!EX.dlg&&!EX.battle){if(exNpcSight())return}}}
